fn main() {
    assert_eq!(u32::MAX.checked_add(1), None);
    assert_eq!(u32::MAX.saturating_add(1), u32::MAX);
    assert!(u8::try_from(300u16).is_err());
    let difference = i64::from(i32::MAX) - i64::from(i32::MIN);
    assert_eq!(difference, 4_294_967_295);
}

